export const files = {
  'components/Gallery.js': "'use client';\n\nimport { useCallback, useEffect, useRef, useState } from 'react';\nimport { createPortal } from 'react-dom';\nimport { portrait, tall } from '../lib/data';\n\nconst MAX_VIDEOS = 19;\nconst MOBILE_LIMIT = 4;\n\n/* One \"Our Works\" photo grid with its Show all / Show less buttons */\nfunction PhotoGrid({ items, gridClass, imgClass, seriesKey, seriesLabel, mobile, expanded, onToggle, onOpen }) {\n  const total = items.length;\n  const limited = mobile && total > MOBILE_LIMIT;\n  const collapsed = limited && !expanded;\n  const lessVisible = limited && expanded;\n\n  return (\n    <div\n      className={'grid-wrapper' + (collapsed ? ' collapsed' : '')}\n      data-mobile-limit={MOBILE_LIMIT}\n      data-series={seriesKey}\n    >\n      <div className={gridClass}>\n        {items.map((it, i) => (\n          <div\n            className=\"gcard\"\n            data-name={it.name}\n            data-series={seriesLabel}\n            key={it.name}\n            onClick={() => onOpen(items, i, seriesLabel)}\n          >\n            <img\n              className={imgClass}\n              src={it.src}\n              alt={it.name}\n              loading={i < 4 ? 'eager' : 'lazy'}\n              decoding=\"async\"\n              sizes=\"(min-width: 1024px) 25vw, (min-width: 640px) 33vw, 50vw\"\n            />\n          </div>\n        ))}\n      </div>\n      <button\n        className={'show-more-btn' + (collapsed ? ' visible' : '')}\n        type=\"button\"\n        onClick={() => onToggle(seriesKey, true)}\n      >\n        {limited ? 'Show all ' + total + ' photos' : 'Show all photos'}\n      </button>\n      <button\n        className={'show-less-btn' + (lessVisible ? ' visible' : '')}\n        type=\"button\"\n        onClick={() => onToggle(seriesKey, false)}\n      >\n        Show less\n      </button>\n    </div>\n  );\n}\n\nexport default function Gallery() {\n  const [mounted, setMounted] = useState(false);\n  const [mobile, setMobile] = useState(false);\n  const [expanded, setExpanded] = useState({ portrait: false, tall: false });\n  const [photo, setPhoto] = useState(null); // { items, index, series }\n  const [video, setVideo] = useState({ open: false, index: 0 });\n\n  const containerRef = useRef(null);\n  const trackRef = useRef(null);\n  const sectionRef = useRef(null);\n  const playerRef = useRef(null);\n  const photoTouchX = useRef(0);\n  const videoTouchX = useRef(0);\n  const stripTouchX = useRef(0);\n\n  useEffect(() => { setMounted(true); }, []);\n\n  /* \u2500\u2500\u2500 Show more / show less: mobile detection \u2500\u2500\u2500 */\n  useEffect(() => {\n    const update = () => setMobile(window.innerWidth <= 767);\n    update();\n    let t;\n    const onResize = () => {\n      clearTimeout(t);\n      t = setTimeout(() => {\n        update();\n        setExpanded({ portrait: false, tall: false });\n      }, 150);\n    };\n    window.addEventListener('resize', onResize, { passive: true });\n    return () => { window.removeEventListener('resize', onResize); clearTimeout(t); };\n  }, []);\n\n  const toggleExpanded = (key, value) => setExpanded((s) => ({ ...s, [key]: value }));\n\n  /* \u2500\u2500\u2500 Photo lightbox \u2500\u2500\u2500 */\n  const openPhoto = useCallback((items, index, series) => setPhoto({ items, index, series }), []);\n  const closePhoto = useCallback(() => setPhoto(null), []);\n  const stepPhoto = useCallback((d) => setPhoto((p) => p && ({ ...p, index: (p.index + d + p.items.length) % p.items.length })), []);\n\n  useEffect(() => {\n    if (!photo) return;\n    const onKey = (e) => {\n      if (e.key === 'Escape') closePhoto();\n      if (e.key === 'ArrowRight') stepPhoto(1);\n      if (e.key === 'ArrowLeft') stepPhoto(-1);\n    };\n    document.addEventListener('keydown', onKey);\n    return () => document.removeEventListener('keydown', onKey);\n  }, [!!photo, closePhoto, stepPhoto]);\n\n  /* \u2500\u2500\u2500 Video lightbox \u2500\u2500\u2500 */\n  const openVideo = (index) => setVideo({ open: true, index });\n  const closeVideo = useCallback(() => setVideo((v) => ({ ...v, open: false })), []);\n  const stepVideo = useCallback((d) => setVideo((v) => ({ ...v, index: (v.index + d + MAX_VIDEOS) % MAX_VIDEOS })), []);\n\n  useEffect(() => {\n    const p = playerRef.current;\n    if (!p) return;\n    if (video.open) {\n      p.innerHTML = '';\n      const src = document.createElement('source');\n      src.src = '/videos/v' + (video.index + 1) + '.mp4';\n      src.type = 'video/mp4';\n      p.appendChild(src);\n      p.load();\n      p.play().catch(() => {});\n    } else {\n      p.pause();\n      p.innerHTML = '';\n    }\n  }, [video.open, video.index]);\n\n  useEffect(() => {\n    if (!video.open) return;\n    const onKey = (e) => {\n      if (e.key === 'Escape') closeVideo();\n      if (e.key === 'ArrowRight') stepVideo(1);\n      if (e.key === 'ArrowLeft') stepVideo(-1);\n    };\n    document.addEventListener('keydown', onKey);\n    return () => document.removeEventListener('keydown', onKey);\n  }, [video.open, closeVideo, stepVideo]);\n\n  /* lock page scroll while either lightbox is open */\n  const anyOpen = !!photo || video.open;\n  useEffect(() => {\n    document.body.style.overflow = anyOpen ? 'hidden' : '';\n    return () => { document.body.style.overflow = ''; };\n  }, [anyOpen]);\n\n  /* \u2500\u2500\u2500 Video strip scroll controls \u2500\u2500\u2500 */\n  const getScrollAmount = () => {\n    const track = trackRef.current;\n    const card = track && track.querySelector('.vcard');\n    return card ? card.offsetWidth + parseInt(getComputedStyle(track).gap) : 250;\n  };\n  const scrollStrip = (dir) =>\n    containerRef.current && containerRef.current.scrollBy({ left: dir * getScrollAmount(), behavior: 'smooth' });\n\n  const cur = photo ? photo.items[photo.index] : null;\n\n  return (\n    <>\n      <section className=\"section\" id=\"gallery\" style={{ background: 'var(--bg)' }}>\n        <div className=\"section-inner\">\n          <div style={{ marginBottom: '2.75rem' }}>\n            <h2 className=\"section-title\">Our<br/><em>Works</em></h2>\n          </div>\n\n          {/* PORTRAIT PHOTOS */}\n          <PhotoGrid\n            items={portrait} gridClass=\"grid-a\" imgClass=\"img-a\" seriesKey=\"portrait\" seriesLabel=\"Portrait\"\n            mobile={mobile} expanded={expanded.portrait} onToggle={toggleExpanded} onOpen={openPhoto}\n          />\n\n          <hr className=\"series-divider\" />\n\n          {/* TALL PHOTOS */}\n          <PhotoGrid\n            items={tall} gridClass=\"grid-b\" imgClass=\"img-b\" seriesKey=\"tall\" seriesLabel=\"Tall\"\n            mobile={mobile} expanded={expanded.tall} onToggle={toggleExpanded} onOpen={openPhoto}\n          />\n\n          <hr className=\"series-divider\" />\n\n          {/* VIDEO CLIPS \u2014 static poster images, no runtime frame extraction */}\n          <div className=\"video-scroll-wrapper\" id=\"video-section\" ref={sectionRef}>\n            <div\n              className=\"video-horizontal-scroll\"\n              id=\"video-scroll-container\"\n              ref={containerRef}\n              onTouchStart={(e) => { stripTouchX.current = e.changedTouches[0].screenX; }}\n              onTouchEnd={(e) => {\n                const diff = e.changedTouches[0].screenX - stripTouchX.current;\n                if (Math.abs(diff) > 50) scrollStrip(diff < 0 ? 1 : -1);\n              }}\n            >\n              <div className=\"video-scroll-track\" id=\"video-track\" ref={trackRef}>\n                {Array.from({ length: MAX_VIDEOS }, (_, i) => (\n                  <div\n                    className=\"vcard\"\n                    key={i}\n                    data-video-src-mp4={'/videos/v' + (i + 1) + '.mp4'}\n                    data-name={'Cake Preview ' + (i + 1)}\n                    onClick={() => openVideo(i)}\n                  >\n                    <img\n                      src={'/images/video-posters/v' + (i + 1) + '.jpg'}\n                      alt={'Cake Preview ' + (i + 1)}\n                      width={252}\n                      height={480}\n                      loading={i < 3 ? 'eager' : 'lazy'}\n                      decoding=\"async\"\n                      sizes=\"200px\"\n                    />\n                    <div className=\"play-icon-overlay\"></div>\n                  </div>\n                ))}\n              </div>\n            </div>\n            <div className=\"video-scroll-controls\">\n              <button className=\"scroll-btn scroll-prev\" aria-label=\"Previous videos\" onClick={() => scrollStrip(-1)}>\u2039</button>\n              <button className=\"scroll-btn scroll-next\" aria-label=\"Next videos\" onClick={() => scrollStrip(1)}>\u203a</button>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      {/* Lightboxes live at the end of <body>, exactly like the original page */}\n      {mounted && createPortal(\n        <>\n          {/* PHOTO LIGHTBOX */}\n          <div\n            className={'lightbox' + (photo ? ' open' : '')}\n            id=\"photo-lightbox\"\n            role=\"dialog\"\n            aria-modal=\"true\"\n            aria-label=\"Image viewer\"\n            onClick={(e) => { if (e.target === e.currentTarget) closePhoto(); }}\n            onTouchStart={(e) => { photoTouchX.current = e.changedTouches[0].screenX; }}\n            onTouchEnd={(e) => {\n              const x = e.changedTouches[0].screenX;\n              if (Math.abs(x - photoTouchX.current) > 50) stepPhoto(x < photoTouchX.current ? 1 : -1);\n            }}\n          >\n            <button className=\"lb-close\" id=\"photo-lb-close\" aria-label=\"Close\" onClick={closePhoto}>\u2715</button>\n            <div className=\"lb-img-wrap\">\n              <img id=\"photo-lb-img\" src={cur ? cur.src : undefined} alt={cur ? cur.name : ''} />\n              <button className=\"lb-nav lb-prev\" id=\"photo-lb-prev\" onClick={() => stepPhoto(-1)}>\u2039</button>\n              <button className=\"lb-nav lb-next\" id=\"photo-lb-next\" onClick={() => stepPhoto(1)}>\u203a</button>\n            </div>\n            <div className=\"lb-info\">\n              <p className=\"lb-info-name\" id=\"photo-lb-name\">{cur ? cur.name : ''}</p>\n              <p className=\"lb-info-sub\" id=\"photo-lb-series\">{photo ? photo.series : ''}</p>\n            </div>\n          </div>\n\n          {/* VIDEO LIGHTBOX */}\n          <div\n            className={'video-lightbox' + (video.open ? ' open' : '')}\n            id=\"video-lightbox\"\n            role=\"dialog\"\n            aria-modal=\"true\"\n            aria-label=\"Video viewer\"\n            onClick={(e) => { if (e.target === e.currentTarget) closeVideo(); }}\n            onTouchStart={(e) => { videoTouchX.current = e.changedTouches[0].screenX; }}\n            onTouchEnd={(e) => {\n              const diff = e.changedTouches[0].screenX - videoTouchX.current;\n              if (Math.abs(diff) > 50) stepVideo(diff < 0 ? 1 : -1);\n            }}\n          >\n            <button className=\"vlb-btn vlb-close\" id=\"video-lb-close\" aria-label=\"Close\" onClick={closeVideo}>\u2715</button>\n            <video id=\"video-lb-player\" ref={playerRef} controls playsInline preload=\"auto\"></video>\n            <div className=\"vlb-controls\">\n              <button className=\"vlb-btn\" id=\"video-lb-prev\" onClick={() => stepVideo(-1)}>\u2039</button>\n              <button className=\"vlb-btn\" id=\"video-lb-next\" onClick={() => stepVideo(1)}>\u203a</button>\n              <button\n                className=\"vlb-btn\"\n                id=\"video-lb-fullscreen\"\n                onClick={() => {\n                  const p = playerRef.current;\n                  if (!p) return;\n                  if (p.requestFullscreen) p.requestFullscreen();\n                  else if (p.webkitRequestFullscreen) p.webkitRequestFullscreen();\n                }}\n              >\u26f6</button>\n            </div>\n            <div className=\"vlb-info\" id=\"video-lb-info\">{'Cake Preview ' + (video.index + 1)}</div>\n          </div>\n        </>,\n        document.body\n      )}\n    </>\n  );\n}\n",
  'components/Tv5.js': "'use client';\n\nimport { useRef, useState } from 'react';\n\nexport default function Tv5() {\n  const videoRef = useRef(null);\n  const [playing, setPlaying] = useState(false);\n  const [failed, setFailed] = useState(false);\n\n  const start = () => {\n    if (playing) return;\n    setPlaying(true);\n    // play() is queued for after the <video> mounts, on the next tick\n    requestAnimationFrame(() => videoRef.current && videoRef.current.play().catch(() => {}));\n  };\n\n  return (\n    <section className=\"tv5-section\" id=\"featured-tv5\" aria-label=\"Featured at TV5\" style={{ paddingTop: '2rem', paddingBottom: '2rem' }}>\n      <div className=\"tv5-inner\">\n        <div className=\"tv5-header\" style={{ marginBottom: '1.5rem' }}>\n          <div className=\"tv5-badge\">\n            <span className=\"tv5-badge-dot\"></span>\n            As Seen On\n          </div>\n          <h2 className=\"tv5-title\">Featured at<br/><em>TV5</em></h2>\n          <p className=\"tv5-subtitle\">Angelyn's Cakes was featured on national television \u2014 a milestone that celebrates years of craft, dedication, and heartfelt service to every client.</p>\n        </div>\n\n        <div className=\"tv5-video-wrap\" id=\"tv5-video-wrap\">\n          {!playing && (\n            <img\n              id=\"tv5-poster-img\"\n              src=\"/images/video-posters/feat.jpg\"\n              alt=\"Angelyn's Cakes featured on TV5\"\n              width={1280}\n              height={720}\n              loading=\"lazy\"\n              decoding=\"async\"\n              style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover', display: 'block', zIndex: 1 }}\n            />\n          )}\n          {playing && (\n            <video\n              ref={videoRef}\n              controls\n              playsInline\n              preload=\"auto\"\n              poster=\"/images/video-posters/feat.jpg\"\n              style={{\n                position: 'absolute', inset: 0, width: '100%', height: '100%',\n                objectFit: 'cover', background: '#000', zIndex: 0,\n                display: failed ? 'none' : undefined,\n              }}\n              onError={() => setFailed(true)}\n            >\n              <source src=\"/videos/feat.mp4\" type=\"video/mp4\" />\n              <source src=\"/videos/feat.webm\" type=\"video/webm\" />\n            </video>\n          )}\n          {failed && (\n            <div style={{ color: '#fff', position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#000', zIndex: 0 }}>\n              Video not available\n            </div>\n          )}\n          <div\n            className={'tv5-play-overlay' + (playing ? ' hidden' : '')}\n            id=\"tv5-play-overlay\"\n            role=\"button\"\n            tabIndex={0}\n            aria-label=\"Play TV5 feature video\"\n            onClick={start}\n            onKeyDown={(e) => {\n              if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); start(); }\n            }}\n          >\n            <div className=\"tv5-play-btn\" aria-hidden=\"true\"></div>\n            <span className=\"tv5-play-label\">Watch Feature</span>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n",
  'components/Hero.js': "'use client';\n\nimport { useEffect, useRef } from 'react';\n\n/* HERO VIDEO \u2014 optimised (ported from index.html)\n   One <video> in the DOM. The source is chosen from the real viewport\n   width so only ONE file is ever fetched. The dark background-color\n   (#2E1510) is the instant placeholder, and the poster shows until the\n   video plays. */\nexport default function Hero() {\n  const vidRef = useRef(null);\n\n  useEffect(() => {\n    const vid = vidRef.current;\n    if (!vid) return;\n\n    const isMobile = window.innerWidth < 768;\n    const src = isMobile ? '/videos/mhero-opt.mp4' : '/videos/dhero.mp4';\n    const poster = isMobile ? '/images/hero-poster-mobile.jpg' : '/images/hero-poster-desktop.jpg';\n\n    vid.poster = poster;\n    vid.muted = true; // React doesn't reliably render the muted attribute; autoplay needs it\n\n    const source = document.createElement('source');\n    source.src = src;\n    source.type = 'video/mp4';\n    vid.appendChild(source);\n\n    const playPromise = vid.play();\n    if (playPromise && typeof playPromise.then === 'function') {\n      playPromise.catch(() => {\n        // Autoplay blocked (e.g. Low Power Mode on iOS) \u2014 poster stays visible\n      });\n    }\n\n    const onVisible = () => {\n      if (!document.hidden) vid.play().catch(() => {});\n    };\n    document.addEventListener('visibilitychange', onVisible);\n\n    return () => {\n      document.removeEventListener('visibilitychange', onVisible);\n      if (source.parentNode === vid) vid.removeChild(source);\n    };\n  }, []);\n\n  return (\n    <section className=\"hero\" aria-label=\"Hero section\">\n      <video\n        id=\"hero-vid\"\n        ref={vidRef}\n        autoPlay\n        loop\n        muted\n        playsInline\n        webkit-playsinline=\"\"\n        preload=\"auto\"\n        disablePictureInPicture\n        disableRemotePlayback\n        style={{ backgroundColor: '#2E1510' }}\n        aria-hidden=\"true\"\n      ></video>\n      <div className=\"hero-overlay\"></div>\n      <div className=\"hero-content\">\n        <h1 className=\"hero-headline\">Cakes that<br/><em>command</em><br/>attention.</h1>\n        <div className=\"hero-btns\">\n          <a href=\"#contact\" className=\"btn-cta\" style={{ fontSize: '0.82rem', padding: '15px 30px' }}>Book a Consultation</a>\n          <a\n            href=\"#bestsellers\"\n            className=\"btn-ghost\"\n            style={{ fontSize: '0.82rem', padding: '15px 30px', color: '#fff', borderColor: 'rgba(255,255,255,0.45)', background: 'rgba(255,255,255,0.08)' }}\n          >See the Collection \u2192</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n",
  'app/layout.js': "import '../css/tailwind.min.css'; // self-hosted, purged Tailwind CSS (same file as before)\nimport './globals.css';           // custom styles extracted from index.html\n\nexport const metadata = {\n  title: \"Angelyn's Cakes \u2014 For Every Occasion\",\n  description:\n    \"Angelyn's Cakes creates bespoke, luxury celebration cakes in Manila. Custom wedding, debut, and corporate cakes. Visit our Makati showroom by appointment.\",\n  keywords:\n    \"custom cakes Manila, wedding cakes, debut cakes, bespoke cakes, cake delivery Makati, Angelyn's Cakes\",\n  alternates: { canonical: 'https://www.angelyncakes.com/' },\n  icons: { icon: [{ url: '/images/icon.png', type: 'image/png' }] },\n};\n\nexport const viewport = {\n  width: 'device-width',\n  initialScale: 1,\n  themeColor: '#C95C72',\n};\n\nconst OG_IMAGE = 'https://res.cloudinary.com/dgbwapcgt/image/upload/v1778334726/thumb_lwhuzr.jpg';\nconst FONTS_URL =\n  'https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;0,900;1,400;1,700&family=DM+Sans:opsz,wght@9..40,300;9..40,400;9..40,500;9..40,600&display=swap';\n\n// Same policy as the original <meta http-equiv> tag. Only applied in production:\n// `next dev` needs 'unsafe-eval' for hot reloading, which this policy forbids.\nconst CSP =\n  \"default-src 'self'; script-src 'self' 'unsafe-inline' https://fonts.googleapis.com https://fonts.gstatic.com; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; img-src 'self' data: blob: https:; media-src 'self' blob:; connect-src 'self' https://fonts.googleapis.com https://fonts.gstatic.com; font-src 'self' https://fonts.gstatic.com; frame-src https://www.google.com;\";\n\nexport default function RootLayout({ children }) {\n  return (\n    <html lang=\"en\">\n      <head>\n        {/* Social sharing */}\n        <meta property=\"og:title\" content=\"Angelyn's Cakes \u2014 For Every Occasion\" />\n        <meta property=\"og:description\" content=\"Custom cakes for weddings, debuts, and corporate events. Handcrafted in Makati.\" />\n        <meta property=\"og:type\" content=\"website\" />\n        <meta property=\"og:url\" content=\"https://www.angelyncakes.com/\" />\n        <meta property=\"og:image\" content={OG_IMAGE} />\n        <meta property=\"og:image:width\" content=\"1200\" />\n        <meta property=\"og:image:height\" content=\"630\" />\n        <meta name=\"twitter:image\" content={OG_IMAGE} />\n        <meta name=\"twitter:title\" content=\"Angelyn's Cakes \u2014 For Every Occasion\" />\n        <meta name=\"twitter:description\" content=\"Custom cakes for weddings, debuts, and corporate events. Handcrafted in Makati.\" />\n\n        {/* Security headers */}\n        <meta name=\"referrer\" content=\"strict-origin-when-cross-origin\" />\n        <meta httpEquiv=\"Referrer-Policy\" content=\"strict-origin-when-cross-origin\" />\n        <meta httpEquiv=\"X-Content-Type-Options\" content=\"nosniff\" />\n        {process.env.NODE_ENV === 'production' && (\n          <meta httpEquiv=\"Content-Security-Policy\" content={CSP} />\n        )}\n        <meta httpEquiv=\"Permissions-Policy\" content=\"geolocation=(), microphone=(), camera=(), payment=(), interest-cohort=()\" />\n\n        <meta name=\"apple-mobile-web-app-capable\" content=\"yes\" />\n        <meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\" />\n\n        <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n        <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossOrigin=\"\" />\n\n        {/* Preload the correct hero video for this viewport so playback starts\n            as early as possible, without fetching the other (unused) variant. */}\n        <link rel=\"preload\" as=\"image\" href=\"/images/hero-poster-mobile.jpg\" media=\"(max-width: 767px)\" fetchPriority=\"high\" />\n        <link rel=\"preload\" as=\"image\" href=\"/images/hero-poster-desktop.jpg\" media=\"(min-width: 768px)\" fetchPriority=\"high\" />\n        <link rel=\"preload\" as=\"video\" type=\"video/mp4\" href=\"/videos/mhero-opt.mp4\" media=\"(max-width: 767px)\" />\n        <link rel=\"preload\" as=\"video\" type=\"video/mp4\" href=\"/videos/dhero.mp4\" media=\"(min-width: 768px)\" />\n\n        {/* Google Fonts (non-blocking): print media until loaded, then switch to all */}\n        <link id=\"gfonts\" href={FONTS_URL} rel=\"stylesheet\" media=\"print\" suppressHydrationWarning />\n        <script\n          dangerouslySetInnerHTML={{\n            __html:\n              \"(function(){var l=document.getElementById('gfonts');if(!l)return;function s(){l.media='all'}if(l.sheet){s()}else{l.addEventListener('load',s)}})();\",\n          }}\n        />\n        <noscript>\n          <link href={FONTS_URL} rel=\"stylesheet\" />\n        </noscript>\n      </head>\n      <body>{children}</body>\n    </html>\n  );\n}\n",
};

export const perfCss = "\n/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 Performance & responsiveness additions (patch) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n/* Let the browser skip layout/paint work for offscreen sections until they\n   scroll near the viewport. Keeps an estimated height so scrollbar/scroll\n   position doesn't jump once content is measured. */\n#gallery,#featured-tv5,#showroom,#reviews,#about,#contact{content-visibility:auto;contain-intrinsic-size:1px 1200px}\n\n/* Smoother, GPU-friendly swiping/scrolling on touch strips */\n.video-horizontal-scroll,.testi-outer{touch-action:pan-x pan-y;-webkit-tap-highlight-color:transparent}\n.gcard,.cake-card,.vcard{touch-action:manipulation}\n\n/* Avoid animating box-shadow directly (paint-heavy); promote hover-animated\n   cards to their own compositor layer only while interacted with. */\n.gcard:hover,.cake-card:hover,.vcard:hover{will-change:transform}\n\n/* Respect users who prefer less motion: stop marquees/pulses and cut\n   hover-triggered transforms, without breaking layout. */\n@media (prefers-reduced-motion:reduce){\n  html{scroll-behavior:auto}\n  .ticker-track,.testi-track,.tv5-badge-dot,.status-dot{animation:none !important}\n  *,*::before,*::after{transition-duration:0.001ms !important;animation-duration:0.001ms !important}\n}\n\n/* Fluid type/spacing tightening on very small phones to avoid overflow-induced\n   reflow/jank on first paint. */\n@media (max-width:360px){\n  .section{padding:3.5rem 1rem}\n  .section-title{font-size:clamp(1.9rem,9vw,3rem)}\n}\n\n/* Hint the compositor about the hero video early so the first frame is\n   promoted as soon as it starts decoding, reducing jank on entry. */\n.hero video{will-change:transform;transform:translateZ(0)}\n";


const args = process.argv.slice(2);
const repoRoot = args[0] ? join(process.cwd(), args[0]) : process.cwd();

function fail(msg) {
  console.error('\n✖ ' + msg + '\n');
  process.exit(1);
}

function ok(msg) {
  console.log('  ✓ ' + msg);
}

if (!existsSync(join(repoRoot, 'package.json')) || !existsSync(join(repoRoot, 'app')) || !existsSync(join(repoRoot, 'components'))) {
  fail(
    `Could not find a Next.js project at:\n    ${repoRoot}\n\n` +
    `Run this script from the root of the AngelynCakes-Nextjs repo, e.g.:\n` +
    `    cd AngelynCakes-Nextjs\n    node optimize-angelyns-cakes.mjs\n\n` +
    `...or pass the path explicitly:\n    node optimize-angelyns-cakes.mjs ./AngelynCakes-Nextjs`
  );
}

console.log(`\nApplying performance & responsiveness patch to:\n  ${repoRoot}\n`);

// ───────────────────────── 1. Backup + write source files ─────────────────────────
console.log('Updating components...');
for (const [relPath, content] of Object.entries(files)) {
  const fullPath = join(repoRoot, relPath);
  if (!existsSync(fullPath)) {
    console.log(`  ! Skipping ${relPath} (file not found at expected path — repo structure may differ)`);
    continue;
  }
  const backupPath = fullPath + '.bak-original';
  if (!existsSync(backupPath)) {
    copyFileSync(fullPath, backupPath);
  }
  writeFileSync(fullPath, content, 'utf8');
  ok(`${relPath} (backup saved as ${relPath}.bak-original)`);
}

// ───────────────────────── 2. Write poster images ─────────────────────────
console.log('\nWriting video poster images (public/images/video-posters/)...');
const posterDir = join(repoRoot, 'public', 'images', 'video-posters');
if (!existsSync(posterDir)) mkdirSync(posterDir, { recursive: true });

let posterCount = 0;
for (const [filename, base64] of Object.entries(posters)) {
  const outPath = join(posterDir, filename);
  writeFileSync(outPath, Buffer.from(base64, 'base64'));
  posterCount++;
}
ok(`${posterCount} poster images written`);

// ───────────────────────── 3. Append perf CSS ─────────────────────────
console.log('\nAppending performance/responsiveness CSS rules...');
const cssPath = join(repoRoot, 'app', 'globals.css');
if (existsSync(cssPath)) {
  const current = readFileSync(cssPath, 'utf8');
  const marker = '/* ────────── Performance & responsiveness additions (patch) ────────── */';
  if (current.includes(marker)) {
    console.log('  ! globals.css already contains the patch CSS — skipping to avoid duplicates');
  } else {
    const backupPath = cssPath + '.bak-original';
    if (!existsSync(backupPath)) copyFileSync(cssPath, backupPath);
    writeFileSync(cssPath, current + '\n' + perfCss, 'utf8');
    ok('app/globals.css updated (backup saved as app/globals.css.bak-original)');
  }
} else {
  console.log('  ! app/globals.css not found — skipping CSS additions');
}

// ───────────────────────── Done ─────────────────────────
console.log(`
Done! Summary of changes:

  • components/Gallery.js — video thumbnails now load from static JPGs
    instead of extracting frames from 19 hidden <video> elements at runtime.
  • components/Tv5.js     — TV5 feature poster is now a static JPG instead
    of being extracted from the video on every page load.
  • components/Hero.js    — minor playback hints (disablePictureInPicture /
    disableRemotePlayback) to reduce browser overhead.
  • app/layout.js         — added responsive <link rel="preload"> hints so
    the correct hero video/poster for the viewport starts fetching sooner.
  • app/globals.css       — added content-visibility for offscreen sections,
    prefers-reduced-motion support, and touch-action hints for swipe areas.
  • public/images/video-posters/*.jpg — 20 new poster images (~390KB total).

Next steps:
  1. Review the diffs (every changed file has a .bak-original next to it).
  2. npm install (if you haven't already)
  3. npm run dev     — verify locally
  4. npm run build   — static export to confirm everything still builds

To revert a file: copy its *.bak-original back over it.
`);
